def _esc(v):
    return str(v).replace(',', '\\,').replace(' ', '\\ ').replace('=', '\\=')

def _field(v):
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int):
        return f'{v}i'
    if isinstance(v, float):
        return repr(v)
    return '"' + str(v).replace('"', '\\"') + '"'

def to_line(measurement, tags, fields, ts_ns):
    head = measurement + ''.join(f',{k}={_esc(tags[k])}' for k in sorted(tags))
    body = ','.join(f'{k}={_field(fields[k])}' for k in sorted(fields))
    return f'{head} {body} {ts_ns}'

