def per_interval(samples, interval_s):
    b = {}
    for t, ms, ok in samples:
        k = t // interval_s * interval_s
        c, e, m = b.get(k, (0, 0, 0))
        b[k] = (c + 1, e + (0 if ok else 1), max(m, ms))
    return [(k,) + v for k, v in sorted(b.items())]
